  for(int i=0;i<3;i++){final String action=PlayerOverlayRules.bottomAction(i);if(findTag(bottom,"mp-slot-"+action)!=null)continue;int kind=PlayerOverlayRules.AUDIO.equals(action)?PlayerIcons.NOTE:PlayerOverlayRules.SUBTITLE.equals(action)?PlayerIcons.CC:PlayerIcons.LIST;String description=PlayerOverlayRules.AUDIO.equals(action)?"音轨":PlayerOverlayRules.SUBTITLE.equals(action)?"字幕":"选集";Button b=icon(a,kind,description,v->dispatch(a,action));b.setTag("mp-slot-"+action);actions.addView(b);}
