  for(int i=0;i<time.getChildCount();i++){View v=time.getChildAt(i);if(v instanceof SeekBar&&v.getLayoutParams() instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams p=(LinearLayout.LayoutParams)v.getLayoutParams();if(p.leftMargin!=0){p.leftMargin=0;v.setLayoutParams(p);}}}
