 static void external(Activity a){JSONObject stream=TrackSelection.stream(a);String url=stream.optString("url");if(stream.has("infoHash")||MagnetLinks.isMagnet(url)){try{OnlineSubtitleSearch.call(a,"external",new Class<?>[0]);}catch(Exception e){toast(a,"没有可用的外部播放器");}return;}externalReplay(a);}
 /** 0.1.114：把当前片源从当前位置交给其他播放器（Just Player 等，杜比视界颜色正确）。 */
 static void externalReplay(Activity a){try{JSONObject stream=TrackSelection.stream(a);String url=stream.optString("url");if(url.isEmpty()||stream.has("infoHash")||MagnetLinks.isMagnet(url)){toast(a,"磁力 / 种子片源不能交给外部播放器");return;}
  int pos=EmbyPlayback.position(a);Object n=OnlineSubtitleSearch.field(a,"name");String title=n==null?meta(a).optString("name",""):n.toString();
  if(ExternalVideo.open(a,url,title,Math.max(0,pos),ExternalVideo.headers(stream)))a.finish();else toast(a,"手机上没有其他播放器，可以装一个 Just Player（支持杜比视界）");}catch(Exception e){toast(a,"无法打开外部播放器");}}
 static void systemReplay(Activity a){try{JSONObject stream=TrackSelection.stream(a);String url=stream.optString("url");if(url.isEmpty()||stream.has("infoHash")||MagnetLinks.isMagnet(url)){toast(a,"磁力 / 种子片源不能用系统解码");return;}
  int pos=EmbyPlayback.position(a);Object n=OnlineSubtitleSearch.field(a,"name");String title=n==null?meta(a).optString("name",""):n.toString();
  SystemPlayerActivity.open(a,stream,id(a),title,Math.max(0,pos),new android.content.Intent(a.getIntent()));a.finish();}catch(Exception e){toast(a,"无法切换到系统解码");}}
 static void introMenu(Activity a){java.util.List<CinemaMenu.Item> rows=new ArrayList<>();
  rows.add(CinemaMenu.item("标记片头开始（当前位置）",()->markIntro(a,true)));
  rows.add(CinemaMenu.item("标记片头结束（当前位置）",()->markIntro(a,false)));
  rows.add(CinemaMenu.item("清除片头标记",()->{String key=EmbyCue.seriesKey(meta(a),name(a));a.getSharedPreferences("data",0).edit().putString("intro.marks",EmbyCue.clearIntro(a.getSharedPreferences("data",0).getString("intro.marks","{}"),key)).apply();toast(a,"已清除片头标记");}));
  CinemaMenu.show(a,"片头标记",rows);}
 static void markIntro(Activity a,boolean start){String key=EmbyCue.seriesKey(meta(a),name(a));if(key.isEmpty()){toast(a,"还不能标记这部片子的片头");return;}int pos=EmbyPlayback.position(a);if(pos<0){toast(a,"还没有播放进度");return;}String store=a.getSharedPreferences("data",0).getString("intro.marks","{}");String next=EmbyCue.writeIntro(store,key,start?Long.valueOf(pos):null,start?null:Long.valueOf(pos));a.getSharedPreferences("data",0).edit().putString("intro.marks",next).apply();toast(a,start?"已标记片头开始":"已标记片头结束");}
 static void click(Button b,String label,ArrayList<String> labels,ArrayList<Runnable> actions){if(b==null)return;labels.add(label);actions.add(()->b.performClick());}

 static void status(Activity a){
  boolean premature=PlaybackRepair.premature(a);
  Object raw=OnlineSubtitleSearch.field(a,"state");String message=raw instanceof TextView?text((TextView)raw):"";
  if(raw instanceof View)((View)raw).setVisibility(View.GONE);
  boolean rendered=Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"rendered")),terminal=Boolean.TRUE.equals(OnlineSubtitleSearch.field(a,"terminal"));
  boolean failure=PlaybackReviewRules.failure(rendered,terminal,message,premature);
  boolean covered=PlayerSidePanel.open(a)||CinemaMenu.isOpen(a)||PlayerGestures.locked(a)||(Build.VERSION.SDK_INT>=24&&a.isInPictureInPictureMode());
  EmbyAutoRecovery.nativeTick(a,failure,covered||!a.hasWindowFocus(),message);
  connectHud(a,!PlaybackReviewRules.feedbackVisible(covered,failure,rendered,terminal,message)?"":failure?PlaybackReviewRules.failureMessage(message):PlaybackReviewRules.loading(message),failure);
 }
 static void connectHud(Activity a,String text,boolean failure){
  View host=root(a);if(!(host instanceof FrameLayout))return;FrameLayout root=(FrameLayout)host;
  View old=root.findViewWithTag("mp-connect");if(old!=null)old.setVisibility(View.GONE);
  LinearLayout box=root.findViewWithTag("mp-playback-feedback");if(failure&&!text.isEmpty()){if(box!=null)box.setVisibility(View.GONE);PlaybackFailureCard.show(a,root,text,()->{if(EmbyAutoRecovery.pending(a))EmbyAutoRecovery.cancel(a);else retrySource(a);},()->{EmbyAutoRecovery.cancel(a);PlayerSidePanel.open(a,PlayerSidePanel.ROUTES);});return;}PlaybackFailureCard.hide(root);if(text.isEmpty()){if(box!=null)box.setVisibility(View.GONE);return;}
  if(box==null){box=new LinearLayout(a);box.setTag("mp-playback-feedback");box.setOrientation(LinearLayout.VERTICAL);box.setGravity(Gravity.CENTER);box.setPadding(dp(a,16),dp(a,12),dp(a,16),dp(a,12));box.setBackground(PlayerTheme.card(a.getResources().getDisplayMetrics().density));root.addView(box,new FrameLayout.LayoutParams(-2,-2,Gravity.CENTER));}
  String key="load:"+text;if(!key.equals(box.getContentDescription())){box.removeAllViews();box.setContentDescription(key);
   ProgressBar progress=new ProgressBar(a);progress.setIndeterminateTintList(android.content.res.ColorStateList.valueOf(PlayerTheme.playbackAccent(CinemaTheme.gold(a))));box.addView(progress,new LinearLayout.LayoutParams(dp(a,28),dp(a,28)));
   TextView label=label(a,14);label.setSingleLine(false);label.setGravity(Gravity.CENTER);label.setMaxWidth(dp(a,300));label.setText(text);box.addView(label,new LinearLayout.LayoutParams(-2,-2));

  }box.setVisibility(View.VISIBLE);
 }
 static void retrySource(Activity a){try{EmbyAutoRecovery.manual(a);JSONObject stream=TrackSelection.stream(a);if(!stream.optString("emby.server").isEmpty()&&!stream.optString("emby.item").isEmpty()){EmbyPlayback.replay(a,-1,-1);return;}
  // stopAttempt clears the resolved URL on terminal failure. Reopen from the retained
  // stream instead of retryCurrentDecoder(), which returns without retrying a null URL.
  android.content.Intent retry=new android.content.Intent(a.getIntent());retry.setClass(a,PlayerActivity.class);retry.putExtra("stream",stream.toString());a.startActivity(retry);a.overridePendingTransition(android.R.anim.fade_in,android.R.anim.fade_out);a.finish();
 }catch(Exception e){toast(a,"暂时无法重新连接，请选择其他片源");PlayerSidePanel.open(a,PlayerSidePanel.ROUTES);}}
 static void nextSource(Activity a){try{Object queue=OnlineSubtitleSearch.field(a,"queue");if(queue==null||!Boolean.TRUE.equals(OnlineSubtitleSearch.call(queue,"hasNext",new Class<?>[0]))){toast(a,"当前地址列表已用完，请选择其他片源");PlayerSidePanel.open(a,PlayerSidePanel.ROUTES);return;}Object budget=OnlineSubtitleSearch.field(a,"budget");if(budget!=null)OnlineSubtitleSearch.call(budget,"manualRestart",new Class<?>[]{long.class},android.os.SystemClock.elapsedRealtime());OnlineSubtitleSearch.call(a,"advance",new Class<?>[]{String.class},"手动换下一个源");}catch(Exception e){toast(a,"暂时无法切换，请选择其他片源");PlayerSidePanel.open(a,PlayerSidePanel.ROUTES);}}
