 static void cues(Activity a){LinearLayout bottom=bar(a,"bottom");Object sub=OnlineSubtitleSearch.field(a,"sub");if(bottom==null||!(sub instanceof View)||bottom.getVisibility()!=View.VISIBLE||bottom.getHeight()<=0)return;View view=(View)sub;if(!(view.getLayoutParams() instanceof FrameLayout.LayoutParams))return;FrameLayout.LayoutParams lp=(FrameLayout.LayoutParams)view.getLayoutParams();int want=bottom.getHeight()+dp(a,8);if(lp.bottomMargin!=want){lp.bottomMargin=want;view.setLayoutParams(lp);}}
